  readonly PictureBox image=new PictureBox();readonly Effect936 draft;readonly bool route;RectangleF bounds;bool end;
  public PointsR3(Bitmap frame,Effect936 effect,bool path){draft=UiR2.Copy(effect);route=path;Text=path?"Trajet — cliquer départ puis arrivée":"Centre du zoom — cliquer dans la vidéo";UiR2.Fit(this,960,560);image.Image=new Bitmap(frame);image.Dock=DockStyle.Fill;image.SizeMode=PictureBoxSizeMode.Zoom;image.BackColor=Color.FromArgb(30,30,30);Controls.Add(image);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=38};var ok=new Button{Text="Valider"};ok.Click+=delegate{effect.ZoomX=draft.ZoomX;effect.ZoomY=draft.ZoomY;effect.FromX=draft.FromX;effect.FromY=draft.FromY;effect.ToX=draft.ToX;effect.ToY=draft.ToY;DialogResult=DialogResult.OK;};bar.Controls.Add(ok);var reset=new Button{Text=path?"Recommencer":"Recentrer",AutoSize=true};reset.Click+=delegate{end=false;draft.ZoomX=draft.ZoomY=50;image.Invalidate();};bar.Controls.Add(reset);bar.Controls.Add(new Button{Text="Annuler",DialogResult=DialogResult.Cancel});Controls.Add(bar);
   image.Paint+=delegate(object s,PaintEventArgs e){float scale=Math.Min(image.Width/(float)frame.Width,image.Height/(float)frame.Height);bounds=new RectangleF((image.Width-frame.Width*scale)/2,(image.Height-frame.Height*scale)/2,frame.Width*scale,frame.Height*scale);Func<double,double,PointF> point=(x,y)=>new PointF(bounds.X+(float)x*bounds.Width/100,bounds.Y+(float)y*bounds.Height/100);if(route){var a=point(draft.FromX,draft.FromY);var b=point(draft.ToX,draft.ToY);e.Graphics.DrawLine(Pens.Cyan,a,b);e.Graphics.FillEllipse(Brushes.Lime,a.X-5,a.Y-5,10,10);e.Graphics.FillEllipse(Brushes.Red,b.X-5,b.Y-5,10,10);}else{var p=point(draft.ZoomX,draft.ZoomY);e.Graphics.DrawLine(Pens.Cyan,p.X-12,p.Y,p.X+12,p.Y);e.Graphics.DrawLine(Pens.Cyan,p.X,p.Y-12,p.X,p.Y+12);}};
   image.MouseDown+=delegate(object s,MouseEventArgs e){if(!bounds.Contains(e.Location))return;double x=(e.X-bounds.X)/bounds.Width*100,y=(e.Y-bounds.Y)/bounds.Height*100;if(route){if(!end){draft.FromX=x;draft.FromY=y;}else{draft.ToX=x;draft.ToY=y;}end=!end;}else{draft.ZoomX=x;draft.ZoomY=y;}image.Invalidate();};FormClosed+=delegate{image.Image.Dispose();};
  }
 }
